const [root,out]=process.argv.slice(2),sha=b=>createHash('sha256').update(b).digest('hex'),blob=(pin,p)=>cp.execFileSync('git',['cat-file','blob',pin+':'+p],{cwd:root,maxBuffer:32e6});
