function seal(){return packets.map(([dir,pin],i)=>{const b=blob(pin,base(i)+'SOURCE_MANIFEST.json'),m=JSON.parse(b);for(const e of [...m.artifacts,{file:base(i)+'SOURCE_MANIFEST.json'}]){const b=blob(pin,e.file);assert.deepEqual(b,fs.readFileSync(path.join(root,e.file)));if(e.sha256){assert.equal(b.length,e.bytes);assert.equal(sha(b),e.sha256);}}return{dir,commit:pin,manifest_artifacts:m.artifacts.length,files_with_manifest:m.artifacts.length+1,manifest_sha256:sha(b)};});}
fs.mkdirSync(out,{recursive:true});const before=seal();let owners=0,hunks=0;
for(const [idx,file,key]of[[0,'COMPLETE_CURRENT_REVERSES.json','proofs'],[1,'COMPLETE_CALLER_REVERSES.json','records'],[1,'COMPLETE_TRANSPORT_REVERSES.json','records']]){const p=JSON.parse(blob(packets[idx][1],base(idx)+file));for(const r of p[key]){let s=blob(packets[idx][1],base(idx)+r.output).toString();assert.equal(sha(s),r.after_sha256);for(const h of [...r.hunks].reverse()){assert.equal(s.split(h.after).length,2);s=s.replace(h.after,()=>h.before);hunks++;}assert.deepEqual(Buffer.from(s),blob(r.source_commit,r.source_path));owners++;}}
